    public static Irradiance Sum(this IEnumerable<Irradiance> values)
    {
        double sum = 0;
        foreach (var v in values) sum += v.SI;
        return Irradiance.FromSI(sum);
    }

    public static Irradiance Average(this IEnumerable<Irradiance> values)
    {
        double sum = 0; long count = 0;
        foreach (var v in values) { sum += v.SI; count++; }
        return count == 0 ? throw new InvalidOperationException("Sequence contains no elements") : Irradiance.FromSI(sum / count);
    }

    public static Irradiance Min(this IEnumerable<Irradiance> values) => Aggregate(values, Math.Min);
    public static Irradiance Max(this IEnumerable<Irradiance> values) => Aggregate(values, Math.Max);

    private static Irradiance Aggregate(IEnumerable<Irradiance> values, Func<double, double, double> pick)
    {
        using var e = values.GetEnumerator();
        if (!e.MoveNext()) throw new InvalidOperationException("Sequence contains no elements");
        var result = e.Current.SI;
        while (e.MoveNext()) result = pick(result, e.Current.SI);
        return Irradiance.FromSI(result);
    }
